import * as room13 from "./parts/room-13.mjs";
import * as room14 from "./parts/room-14.mjs";
import * as room15 from "./parts/room-15.mjs";

const out = process.argv[2];
if (!out) throw new Error("usage: node build.mjs <out.nbt>");

// Site x0..43, y0..17, z0..31 (plan.md SITE). Grid version 26.3: the palette's ids (iron_chain) are 26.x names.
const g = new Grid([44, 18, 32], { dataVersion: DATA_VERSIONS["26.3"] });
g.fill([0, 0, 0], [43, 0, 31], "grass_block");

runParts(g, [
  ["shell", shell.build],
  ["roofs", roofs.build],
  ["entry and garage front", entry.build],
  ["windows and shutters", windows.build],
  ["site and deck", site.build],
  ["doors and finish", finish.build],
  ["room: foyer", room1.build],
  ["room: office", room2.build],
  ["room: dining room", room3.build],
  ["room: family room", room4.build],
  ["room: kitchen", room5.build],
  ["room: mudroom", room6.build],
  ["room: garage", room7.build],
  ["room: upper hall and gallery", room8.build],
  ["room: bedroom 2", room9.build],
  ["room: bedroom 3", room10.build],
  ["room: primary bedroom", room11.build],
  ["room: walk-in closet", room12.build],
  ["room: primary bathroom", room13.build],
  ["room: bedroom 4", room14.build],
  ["room: bonus room", room15.build],
], { palette: "palette.json" });

g.save(out);
console.log(`saved ${out}`);
#!/bin/sh
# Makes build.nbt from scratch: build.mjs into a temp dir, then the roof preset step once the shell is real (dry-run
# first, the real run only if the dry-run is clean), then into place. Skips the roof step while parts/shell.mjs is a stub.
set -eu
cd "$(dirname "$0")"
MCD=/Volumes/ext1/swe/repos/minecraft-design/tools/bin/mcd.mjs
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

node build.mjs "$TMP/build.nbt"

if grep -q STUB parts/shell.mjs; then
  echo "shell is still a stub: roof step skipped"
else
  # R-main (plan.md Roofs). Preset civic with the plan's overrides; R-turret cone is added after this, by the roofs worker.
  ROOF_FLAGS="--preset civic --front n --overhang 1 --material slate --eave cornice --trim smooth_quartz --ridge slab --pediment n --dormers 2:s:gable --keep 1,10,6,8,30,11 --keep 0,0,19,1,30,24"
  node "$MCD" roof "$TMP/build.nbt" "$TMP/roofed.nbt" $ROOF_FLAGS --dry-run
  node "$MCD" roof "$TMP/build.nbt" "$TMP/roofed.nbt" $ROOF_FLAGS
  mv "$TMP/roofed.nbt" "$TMP/build.nbt"
fi

mv "$TMP/build.nbt" build.nbt
echo "wrote build.nbt"
